import { ChipCellDefinition, LinkCellDefinition, NumberCellDefinition, TextCellDefinition, TextHeaderCellDefinition, } from '@atlasng/design-system/table/columns';
/** Start-aligned sortable text header. */
const START_HEADER = { headerTemplate: TextHeaderCellDefinition, headerConfig: { align: 'start' } };
/** End-aligned sortable text header. */
const END_HEADER = { headerTemplate: TextHeaderCellDefinition, headerConfig: { align: 'end' } };
/**
 * Creates a column whose cells link to the row property's value, sized like the
 * Figma title column. Rows sort by the displayed label when it comes from a
 * row property or function.
 *
 * Build columns once and reuse the array; the table caches cell templates by
 * column identity.
 *
 * @param name Header label.
 * @param prop Row property holding the link command, such as a URL.
 * @param label Static label, `labelProp`, or `labelFn` for the link text.
 * @param overrides Column settings replacing the defaults.
 * @returns Link column definition.
 */
export function kgExplorerLinkColumn(name, prop, label, overrides = {}) {
    const labelFor = (row) => label.labelFn?.(row) ?? (label.labelProp !== undefined ? String(row[label.labelProp] ?? '') : (label.label ?? ''));
    return {
        name,
        prop,
        minWidth: 140,
        flexGrow: 1,
        comparator: (_a, _b, rowA, rowB) => labelFor(rowA).localeCompare(labelFor(rowB)),
        cellTemplate: LinkCellDefinition,
        cellConfig: label,
        ...START_HEADER,
        ...overrides,
    };
}
/**
 * Creates a start-aligned text column, sized like the Figma string column.
 *
 * @param name Header label.
 * @param prop Row property displayed in the cells.
 * @param overrides Column settings replacing the defaults.
 * @returns Text column definition.
 */
export function kgExplorerTextColumn(name, prop, overrides = {}) {
    return {
        name,
        prop,
        minWidth: 140,
        cellTemplate: TextCellDefinition,
        ...START_HEADER,
        ...overrides,
    };
}
/**
 * Creates an unsortable column that renders each array value as a stateless
 * chip, like the Figma Organs column. A scalar value renders a single chip and
 * empty values render nothing.
 *
 * @param name Header label.
 * @param prop Row property holding the chip values.
 * @param overrides Column settings replacing the defaults.
 * @returns Chip column definition.
 */
export function kgExplorerChipColumn(name, prop, overrides = {}) {
    return {
        name,
        prop,
        flexGrow: 1,
        minWidth: 248,
        sortable: false,
        cellTemplate: ChipCellDefinition,
        ...START_HEADER,
        ...overrides,
    };
}
/**
 * Creates an end-aligned, localized number column, sized like the Figma number columns.
 *
 * @param name Header label.
 * @param prop Row property holding the number.
 * @param overrides Column settings replacing the defaults.
 * @returns Number column definition.
 */
export function kgExplorerNumberColumn(name, prop, overrides = {}) {
    return {
        name,
        prop,
        minWidth: 96,
        cellTemplate: NumberCellDefinition,
        ...END_HEADER,
        ...overrides,
    };
}
/**
 * Creates an end-aligned date column for preformatted values, sized like the
 * Figma date column.
 *
 * @param name Header label.
 * @param prop Row property holding the formatted date.
 * @param overrides Column settings replacing the defaults.
 * @returns Date column definition.
 */
export function kgExplorerDateColumn(name, prop, overrides = {}) {
    return {
        name,
        prop,
        minWidth: 136,
        cellTemplate: TextCellDefinition,
        cellConfig: { align: 'end' },
        ...END_HEADER,
        ...overrides,
    };
}
